import 'dart:math' as math;
import 'package:flutter/material.dart';

enum DiagnosticArt { formMushroom, formBall, formCrust, formOther, gills, pores, teeth, folds, gillFree, gillAttached, gillDecurrent, ring, volva, ringVolva, capSmooth, capFibrous, capScaly, capSlimy, sporeWhite, sporePink, sporeBrown, sporeDark, stemReticulate, stemScabrous, stemSmooth, soil, wood, moss, dung, hygrophanous, stableCap, bruiseBlue, bruiseOther, noBruise, latex, noLatex, brittle, fibrous, solitary, grouped, clustered, ringGrowth, deciduous, conifer, small, medium, large, smell, noSmell, unknown }
DiagnosticArt artFor(String label){final s=label.toLowerCase();if(s=='hoed + steel')return DiagnosticArt.formMushroom;if(s.contains('bol-/buikvormig'))return DiagnosticArt.formBall;if(s.contains('hout-/korstvormig'))return DiagnosticArt.formCrust;if(s=='andere vorm')return DiagnosticArt.formOther;if(s.contains('plaatjes'))return DiagnosticArt.gills;if(s.contains('buisjes')||s.contains('poriën'))return DiagnosticArt.pores;if(s.contains('tanden')||s.contains('stekels'))return DiagnosticArt.teeth;if(s.contains('plooien')||s.contains('ribben'))return DiagnosticArt.folds;if(s=='vrij')return DiagnosticArt.gillFree;if(s=='aangehecht')return DiagnosticArt.gillAttached;if(s=='aflopend')return DiagnosticArt.gillDecurrent;if(s=='ring')return DiagnosticArt.ring;if(s.contains('beurs')&&!s.contains('beide'))return DiagnosticArt.volva;if(s=='beide')return DiagnosticArt.ringVolva;if(s=='glad')return DiagnosticArt.capSmooth;if(s=='vezelig')return DiagnosticArt.capFibrous;if(s.contains('schubbig / wrattig'))return DiagnosticArt.capScaly;if(s.contains('kleverig'))return DiagnosticArt.capSlimy;if(s.contains('wit / crème'))return DiagnosticArt.sporeWhite;if(s=='roze')return DiagnosticArt.sporePink;if(s.contains('bruin / roest'))return DiagnosticArt.sporeBrown;if(s.contains('purperbruin'))return DiagnosticArt.sporeDark;if(s=='netvormig')return DiagnosticArt.stemReticulate;if(s.contains('schubbig / gestippeld'))return DiagnosticArt.stemScabrous;if(s.contains('glad / anders'))return DiagnosticArt.stemSmooth;if(s.contains('bodem')||s.contains('strooisel'))return DiagnosticArt.soil;if(s.contains('hout'))return DiagnosticArt.wood;if(s.contains('gras / mos'))return DiagnosticArt.moss;if(s.contains('mest'))return DiagnosticArt.dung;if(s=='ja')return DiagnosticArt.hygrophanous;if(s=='nee')return DiagnosticArt.stableCap;if(s.contains('blauw verkleurend'))return DiagnosticArt.bruiseBlue;if(s.contains('andere verkleuring')||s.contains('verkleurt bij'))return DiagnosticArt.bruiseOther;if(s.contains('geen verkleuring')||s.contains('geen duidelijke reactie'))return DiagnosticArt.noBruise;if(s=='melksap aanwezig')return DiagnosticArt.latex;if(s=='geen melksap')return DiagnosticArt.noLatex;if(s.contains('broos'))return DiagnosticArt.brittle;if(s.contains('vlezig / vezelig'))return DiagnosticArt.fibrous;if(s=='afzonderlijk')return DiagnosticArt.solitary;if(s=='groepjes')return DiagnosticArt.grouped;if(s.contains('bundels'))return DiagnosticArt.clustered;if(s.contains('heksenkring'))return DiagnosticArt.ringGrowth;if(s=='loofboom')return DiagnosticArt.deciduous;if(s=='naaldboom')return DiagnosticArt.conifer;if(s=='klein')return DiagnosticArt.small;if(s=='middelgroot')return DiagnosticArt.medium;if(s=='groot')return DiagnosticArt.large;if(s=='opvallende geur')return DiagnosticArt.smell;if(s=='geen opvallende geur')return DiagnosticArt.noSmell;return DiagnosticArt.unknown;}
class DiagnosticIllustration extends StatelessWidget{const DiagnosticIllustration({super.key,required this.art,this.size=72});final DiagnosticArt art;final double size;@override Widget build(BuildContext context)=>SizedBox(width:size,height:size,child:CustomPaint(painter:_Painter(art,Theme.of(context).colorScheme)));}
class _Painter extends CustomPainter{_Painter(this.art,this.cs);final DiagnosticArt art;final ColorScheme cs;Paint line([double w=2])=>Paint()..color=cs.onSurface..style=PaintingStyle.stroke..strokeWidth=w..strokeCap=StrokeCap.round;@override void paint(Canvas c,Size z){final w=z.width,h=z.height,p=line();void cap([double dx=0]){c.drawArc(Rect.fromLTWH(w*(.12+dx),h*.18,w*.76,h*.36),3.25,2.92,false,p);c.drawLine(Offset(w*(.13+dx),h*.38),Offset(w*(.87+dx),h*.38),p);c.drawLine(Offset(w*(.43+dx),h*.38),Offset(w*(.40+dx),h*.88),p);c.drawLine(Offset(w*(.57+dx),h*.38),Offset(w*(.60+dx),h*.88),p);}void miniMush(double x,double y,double scale){c.drawArc(Rect.fromCenter(center:Offset(w*x,h*y),width:w*.25*scale,height:h*.18*scale),math.pi,math.pi,false,p);c.drawLine(Offset(w*x,h*y),Offset(w*x,h*(y+.25*scale)),p);}switch(art){case DiagnosticArt.formMushroom:cap();break;case DiagnosticArt.formBall:c.drawCircle(Offset(w*.5,h*.52),w*.27,p);c.drawLine(Offset(w*.5,h*.79),Offset(w*.5,h*.88),p);break;case DiagnosticArt.formCrust:c.drawLine(Offset(w*.10,h*.70),Offset(w*.90,h*.70),line(3));c.drawRRect(RRect.fromRectAndRadius(Rect.fromLTWH(w*.18,h*.38,w*.64,h*.25),Radius.circular(w*.12)),p);break;case DiagnosticArt.formOther:c.drawPath(Path()..moveTo(w*.18,h*.72)..quadraticBezierTo(w*.32,h*.18,w*.50,h*.48)..quadraticBezierTo(w*.68,h*.78,w*.82,h*.28),line(3));break;case DiagnosticArt.gills:cap();for(var i=0;i<9;i++)c.drawLine(Offset(w*.5,h*.38),Offset(w*(.18+i*.08),h*.54),line(1));break;case DiagnosticArt.pores:cap();for(var y=0;y<3;y++)for(var x=0;x<7;x++)c.drawCircle(Offset(w*(.24+x*.085),h*(.43+y*.06)),w*.018,line(1));break;case DiagnosticArt.teeth:cap();for(var i=0;i<10;i++){final x=w*(.18+i*.07);c.drawLine(Offset(x,h*.40),Offset(x,h*(.48+(i%2)*.05)),line(1.3));}break;case DiagnosticArt.folds:cap();for(var i=0;i<7;i++){final x=w*(.23+i*.09);c.drawPath(Path()..moveTo(w*.5,h*.38)..quadraticBezierTo(x,h*.44,x,h*.55),line(1.4));}break;case DiagnosticArt.gillFree:case DiagnosticArt.gillAttached:case DiagnosticArt.gillDecurrent:c.drawLine(Offset(w*.48,h*.18),Offset(w*.48,h*.88),p);c.drawLine(Offset(w*.56,h*.18),Offset(w*.56,h*.88),p);if(art==DiagnosticArt.gillFree){c.drawLine(Offset(w*.12,h*.38),Offset(w*.40,h*.38),p);c.drawLine(Offset(w*.64,h*.38),Offset(w*.90,h*.38),p);}else if(art==DiagnosticArt.gillAttached){c.drawLine(Offset(w*.12,h*.38),Offset(w*.48,h*.38),p);c.drawLine(Offset(w*.56,h*.38),Offset(w*.90,h*.38),p);}else{c.drawLine(Offset(w*.12,h*.30),Offset(w*.48,h*.48),p);c.drawLine(Offset(w*.56,h*.48),Offset(w*.90,h*.30),p);}break;case DiagnosticArt.ring:case DiagnosticArt.volva:case DiagnosticArt.ringVolva:cap();if(art!=DiagnosticArt.volva)c.drawOval(Rect.fromCenter(center:Offset(w*.5,h*.58),width:w*.32,height:h*.10),p);if(art!=DiagnosticArt.ring)c.drawArc(Rect.fromLTWH(w*.30,h*.75,w*.40,h*.18),0,math.pi,false,p);break;case DiagnosticArt.capSmooth:case DiagnosticArt.capFibrous:case DiagnosticArt.capScaly:case DiagnosticArt.capSlimy:cap();if(art==DiagnosticArt.capFibrous)for(var i=0;i<7;i++)c.drawLine(Offset(w*(.25+i*.08),h*.24),Offset(w*(.20+i*.10),h*.36),line(1));if(art==DiagnosticArt.capScaly)for(var i=0;i<7;i++)c.drawArc(Rect.fromCenter(center:Offset(w*(.25+i*.08),h*(.27+(i%2)*.06)),width:w*.09,height:h*.06),0,math.pi,false,line(1));if(art==DiagnosticArt.capSlimy)c.drawArc(Rect.fromLTWH(w*.18,h*.13,w*.64,h*.20),3.2,2.8,false,line(4));break;case DiagnosticArt.sporeWhite:case DiagnosticArt.sporePink:case DiagnosticArt.sporeBrown:case DiagnosticArt.sporeDark:final color=art==DiagnosticArt.sporeWhite?Colors.white:art==DiagnosticArt.sporePink?const Color(0xffd79a9a):art==DiagnosticArt.sporeBrown?const Color(0xff8b5a3c):const Color(0xff3f3036);c.drawCircle(Offset(w*.5,h*.5),w*.29,Paint()..color=color);c.drawCircle(Offset(w*.5,h*.5),w*.29,line(1));for(var i=0;i<16;i++){final a=i*2*math.pi/16;c.drawLine(Offset(w*.5,h*.5),Offset(w*.5+math.cos(a)*w*.26,h*.5+math.sin(a)*w*.26),Paint()..color=cs.outline.withValues(alpha:.35)..strokeWidth=1);}break;case DiagnosticArt.stemReticulate:case DiagnosticArt.stemScabrous:case DiagnosticArt.stemSmooth:c.drawRRect(RRect.fromRectAndRadius(Rect.fromLTWH(w*.35,h*.10,w*.30,h*.80),Radius.circular(w*.10)),p);if(art==DiagnosticArt.stemReticulate)for(var y=.22;y<.80;y+=.13){c.drawLine(Offset(w*.37,h*y),Offset(w*.63,h*(y+.10)),line(1));c.drawLine(Offset(w*.63,h*y),Offset(w*.37,h*(y+.10)),line(1));}if(art==DiagnosticArt.stemScabrous)for(var y=.20;y<.85;y+=.12){c.drawCircle(Offset(w*.43,h*y),2,p);c.drawCircle(Offset(w*.57,h*(y+.05)),2,p);}break;case DiagnosticArt.soil:case DiagnosticArt.wood:case DiagnosticArt.moss:case DiagnosticArt.dung:c.drawLine(Offset(w*.10,h*.68),Offset(w*.90,h*.68),p);if(art==DiagnosticArt.wood)c.drawRRect(RRect.fromRectAndRadius(Rect.fromLTWH(w*.15,h*.43,w*.70,h*.22),const Radius.circular(8)),p);else if(art==DiagnosticArt.moss)for(var i=0;i<8;i++)c.drawArc(Rect.fromLTWH(w*(.12+i*.1),h*.48,w*.12,h*.20),3.2,2.8,false,p);else if(art==DiagnosticArt.dung)c.drawOval(Rect.fromLTWH(w*.25,h*.48,w*.50,h*.20),p);else for(var i=0;i<10;i++)c.drawCircle(Offset(w*(.12+i*.08),h*(.72+(i%2)*.07)),2,p);break;case DiagnosticArt.hygrophanous:case DiagnosticArt.stableCap:c.drawArc(Rect.fromLTWH(w*.10,h*.25,w*.35,h*.25),math.pi,math.pi,false,p);c.drawArc(Rect.fromLTWH(w*.55,h*.25,w*.35,h*.25),math.pi,math.pi,false,p);if(art==DiagnosticArt.hygrophanous)c.drawArc(Rect.fromLTWH(w*.60,h*.29,w*.25,h*.15),math.pi,math.pi,false,line(5));c.drawLine(Offset(w*.5,h*.15),Offset(w*.5,h*.75),line(1));break;case DiagnosticArt.bruiseBlue:case DiagnosticArt.bruiseOther:case DiagnosticArt.noBruise:c.drawOval(Rect.fromLTWH(w*.16,h*.20,w*.68,h*.58),p);c.drawLine(Offset(w*.50,h*.20),Offset(w*.50,h*.78),line(1));if(art!=DiagnosticArt.noBruise)c.drawCircle(Offset(w*.64,h*.50),w*.13,Paint()..color=art==DiagnosticArt.bruiseBlue?const Color(0xff6489a8):cs.tertiaryContainer);break;case DiagnosticArt.latex:case DiagnosticArt.noLatex:c.drawLine(Offset(w*.15,h*.30),Offset(w*.85,h*.30),p);for(var i=0;i<6;i++)c.drawLine(Offset(w*(.20+i*.11),h*.30),Offset(w*(.20+i*.11),h*.62),line(1));if(art==DiagnosticArt.latex){c.drawPath(Path()..moveTo(w*.5,h*.48)..quadraticBezierTo(w*.43,h*.62,w*.5,h*.72)..quadraticBezierTo(w*.57,h*.62,w*.5,h*.48),p);}break;case DiagnosticArt.brittle:case DiagnosticArt.fibrous:c.drawRect(Rect.fromLTWH(w*.22,h*.20,w*.56,h*.58),p);if(art==DiagnosticArt.brittle){c.drawPath(Path()..moveTo(w*.48,h*.20)..lineTo(w*.42,h*.38)..lineTo(w*.57,h*.48)..lineTo(w*.45,h*.78),line(2));}else for(var i=0;i<5;i++)c.drawLine(Offset(w*(.32+i*.09),h*.25),Offset(w*(.28+i*.09),h*.72),line(1));break;case DiagnosticArt.solitary:miniMush(.5,.45,1);break;case DiagnosticArt.grouped:miniMush(.30,.48,.7);miniMush(.52,.42,.8);miniMush(.72,.50,.65);break;case DiagnosticArt.clustered:for(var i=0;i<5;i++)miniMush(.28+i*.11,.45+(i%2)*.05,.65);break;case DiagnosticArt.ringGrowth:for(var i=0;i<8;i++){final a=i*2*math.pi/8;miniMush(.5+math.cos(a)*.27,.5+math.sin(a)*.20,.35);}break;case DiagnosticArt.deciduous:case DiagnosticArt.conifer:c.drawLine(Offset(w*.5,h*.38),Offset(w*.5,h*.90),line(5));if(art==DiagnosticArt.deciduous)c.drawCircle(Offset(w*.5,h*.30),w*.25,p);else{for(var y=.18;y<.62;y+=.13)c.drawLine(Offset(w*.5,h*y),Offset(w*(.18+y*.2),h*(y+.18)),p);for(var y=.18;y<.62;y+=.13)c.drawLine(Offset(w*.5,h*y),Offset(w*(.82-y*.2),h*(y+.18)),p);}break;case DiagnosticArt.small:case DiagnosticArt.medium:case DiagnosticArt.large:final scale=art==DiagnosticArt.small ? .45 : art==DiagnosticArt.medium ? .7 : 1.0;miniMush(.5,.45,scale);c.drawLine(Offset(w*.15,h*.88),Offset(w*.85,h*.88),line(1));for(var i=0;i<6;i++)c.drawLine(Offset(w*(.20+i*.12),h*.84),Offset(w*(.20+i*.12),h*.92),line(1));break;case DiagnosticArt.smell:case DiagnosticArt.noSmell:cap();if(art==DiagnosticArt.smell)for(var i=0;i<3;i++)c.drawPath(Path()..moveTo(w*(.65+i*.08),h*.18)..quadraticBezierTo(w*(.58+i*.08),h*.08,w*(.68+i*.08),h*.02),line(1.5));break;case DiagnosticArt.unknown:final tp=TextPainter(text:TextSpan(text:'?',style:TextStyle(fontSize:w*.42,color:cs.onSurfaceVariant,fontWeight:FontWeight.bold)),textDirection:TextDirection.ltr)..layout();tp.paint(c,Offset(w*.5-tp.width/2,h*.5-tp.height/2));break;}}
